package com.example.mobileapp.core.geo

object HexGeoJsonMapper {
    fun toFeatureCollectionJson(hexIndexer: HexIndexer, hexIds: Collection<String>): String {
        val features = hexIds.mapNotNull { hexId ->
            runCatching {
                val boundary = hexIndexer.hexBoundary(hexId)
                if (boundary.isEmpty()) return@runCatching null

                // Removed .reversed() because H3 natively returns counter-clockwise points
                val ringCoordinates = buildString {
                    append(boundary.joinToString(",") { "[${it.longitude},${it.latitude}]" })
                    append(",[${boundary.first().longitude},${boundary.first().latitude}]")
                }

                """{"type":"Feature","geometry":{"type":"Polygon","coordinates":[[$ringCoordinates]]},"properties":{"hexId":"$hexId"}}"""
            }.getOrNull()
        }
        return """{"type":"FeatureCollection","features":[${features.joinToString(",")}]}"""
    }
}

package com.example.mobileapp.core.geo

import org.maplibre.geojson.Feature
import org.maplibre.geojson.FeatureCollection
import org.maplibre.geojson.Point
import org.maplibre.geojson.Polygon

object HexGeoJsonMapper {
    fun toFeatureCollection(hexIndexer: HexIndexer, hexIds: Collection<String>): FeatureCollection {
        val features = hexIds.mapNotNull { hexId ->
            runCatching {
                val boundary = hexIndexer.hexBoundary(hexId)
                if (boundary.isEmpty()) return@runCatching null

                val points = boundary.map { Point.fromLngLat(it.longitude, it.latitude) }
                val closedPoints = points + points.first()
                val polygon = Polygon.fromLngLats(listOf(closedPoints))

                Feature.fromGeometry(polygon).apply {
                    addStringProperty("hexId", hexId)
                }
            }.getOrNull()
        }
        return FeatureCollection.fromFeatures(features)
    }
}

package com.example.mobileapp.core.geo

import android.util.Log
import com.example.mobileapp.core.model.GeoPoint
import com.uber.h3core.H3Core

class UberH3HexIndexer : HexIndexer {
    private val h3CoreOrNull: H3Core? by lazy {
        runCatching { H3Core.newInstance() }
            .onFailure { throwable ->
                Log.e("UberH3HexIndexer", "Failed to initialize H3Core natives", throwable)
            }
            .getOrNull()
    }

    override fun isAvailable(): Boolean = h3CoreOrNull != null

    override fun latLngToHexId(latitude: Double, longitude: Double, resolution: Int): String {
        val h3Core = h3CoreOrNull ?: return ""
        return h3Core.latLngToCellAddress(latitude, longitude, resolution)
    }

    override fun hexBoundary(hexId: String): List<GeoPoint> {
        val h3Core = h3CoreOrNull ?: return emptyList()
        if (hexId.isBlank()) return emptyList()
        return h3Core.cellToBoundary(hexId).map { GeoPoint(it.lat, it.lng) }
    }
}

package com.example.mobileapp.core.geo

import android.util.Log
import com.example.mobileapp.core.model.GeoPoint
import com.uber.h3core.H3Core

class UberH3HexIndexer : HexIndexer {
    private val h3CoreOrNull: H3Core? by lazy {
        runCatching {
            // Load native H3 libraries from app-packaged jniLibs.
            H3Core.newSystemInstance()
        }
            .onFailure { throwable ->
                Log.e("UberH3HexIndexer", "Failed to initialize H3Core from jniLibs", throwable)
            }
            .getOrNull()
    }

    override fun isAvailable(): Boolean = h3CoreOrNull != null

    override fun latLngToHexId(latitude: Double, longitude: Double, resolution: Int): String {
        val h3Core = h3CoreOrNull ?: return ""
        return h3Core.latLngToCellAddress(latitude, longitude, resolution)
    }

    override fun hexBoundary(hexId: String): List<GeoPoint> {
        val h3Core = h3CoreOrNull ?: return emptyList()
        if (hexId.isBlank()) return emptyList()
        return h3Core.cellToBoundary(hexId).map { GeoPoint(it.lat, it.lng) }
    }
}

package com.example.mobileapp.features.capture

import cafe.adriel.voyager.core.model.ScreenModel
import com.example.mobileapp.core.capture.HexCaptureEngine
import com.example.mobileapp.core.data.local.HexRepository
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.plus
import org.orbitmvi.orbit.ContainerHost
import org.orbitmvi.orbit.container
import org.orbitmvi.orbit.syntax.simple.intent
import org.orbitmvi.orbit.syntax.simple.reduce

class CaptureScreenModel(
    private val hexCaptureEngine: HexCaptureEngine,
    hexRepository: HexRepository
) : ScreenModel, ContainerHost<CaptureState, Nothing> {

    private val screenModelScope = CoroutineScope(Dispatchers.Main + SupervisorJob())
    private val captureThresholdSteps = 50

    override val container = screenModelScope.container<CaptureState, Nothing>(CaptureState())

    init {
        hexCaptureEngine.state
            .onEach { snapshot ->
                intent {
                    reduce {
                        state.copy(
                            isTracking = snapshot.isTracking,
                            currentLocation = snapshot.currentLocation,
                            currentHexId = snapshot.currentHexId,
                            sessionSteps = snapshot.sessionSteps,
                            // Save live session hexes here
                            sessionCapturedHexes = snapshot.hexesToSteps
                                .filterValues { it >= captureThresholdSteps }
                                .keys
                                .toList()
                        )
                    }
                }
            }
            .launchIn(screenModelScope)

        hexRepository.observeCapturedHexes()
            .onEach { persisted ->
                intent {
                    // Save historical DB hexes here
                    reduce {
                        state.copy(historicalCapturedHexes = persisted.map { it.hexId })
                    }
                }
            }
            .launchIn(screenModelScope)
    }

    fun onToggleTracking() = intent {
        if (state.isTracking) {
            hexCaptureEngine.stopTracking()
        } else {
            hexCaptureEngine.startTracking()
        }
    }

    override fun onDispose() {
        hexCaptureEngine.stopTracking()
        screenModelScope.cancel()
    }
}

package com.example.mobileapp.features.capture

import cafe.adriel.voyager.core.model.ScreenModel
import com.example.mobileapp.core.capture.HexCaptureEngine
import com.example.mobileapp.core.data.local.HexRepository
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import org.orbitmvi.orbit.ContainerHost
import org.orbitmvi.orbit.container
import org.orbitmvi.orbit.syntax.simple.intent
import org.orbitmvi.orbit.syntax.simple.reduce

class CaptureScreenModel(
    private val hexCaptureEngine: HexCaptureEngine,
    hexRepository: HexRepository
) : ScreenModel, ContainerHost<CaptureState, Nothing> {

    // TODO(refactor-capture-state): migrate captured hex storage to LinkedHashSet in state/event reducers.
    private val screenModelScope = CoroutineScope(Dispatchers.Main + SupervisorJob())
    // TODO(refactor-threshold): move capture threshold to config/remote settings.
    private val captureThresholdSteps = 1

    override val container = screenModelScope.container<CaptureState, Nothing>(CaptureState())

    init {
        hexCaptureEngine.state
            .onEach { snapshot ->
                intent {
                    reduce {
                        val newSessionHexes = snapshot.hexesToSteps
                            .filterValues { it >= captureThresholdSteps }
                            .keys
                            .toList()

                        state.copy(
                            isTracking = snapshot.isTracking,
                            currentLocation = snapshot.currentLocation,
                            currentHexId = snapshot.currentHexId,
                            sessionSteps = snapshot.sessionSteps,
                            // Save live session hexes here
                            sessionCapturedHexes = newSessionHexes,
                            // Keep the merged list precomputed to reduce UI work.
                            allCapturedHexes = (newSessionHexes + state.historicalCapturedHexes).distinct()
                        )
                    }
                }
            }
            .launchIn(screenModelScope)

        hexRepository.observeCapturedHexes()
            .onEach { persisted ->
                intent {
                    // Save historical DB hexes here
                    reduce {
                        val history = persisted.map { it.hexId }
                        state.copy(
                            historicalCapturedHexes = history,
                            // Keep the merged list precomputed to reduce UI work.
                            allCapturedHexes = (state.sessionCapturedHexes + history).distinct()
                        )
                    }
                }
            }
            .launchIn(screenModelScope)
    }

    fun onToggleTracking() = intent {
        if (state.isTracking) {
            hexCaptureEngine.stopTracking()
        } else {
            hexCaptureEngine.startTracking()
        }
    }

    override fun onDispose() {
        hexCaptureEngine.stopTracking()
        screenModelScope.cancel()
    }
}

package com.example.mobileapp.features.capture
import com.example.mobileapp.core.model.GeoPoint
data class CaptureState( val isTracking: Boolean = false, val currentLocation: GeoPoint? = null, val currentHexId: String? = null, val sessionSteps: Int = 0, val sessionCapturedHexes: List<String> = emptyList(), val historicalCapturedHexes: List<String> = emptyList() ) { // A helper to merge both lists dynamically for the UI val allCapturedHexes: List<String> get() = (sessionCapturedHexes + historicalCapturedHexes).distinct() }

package com.example.mobileapp.ui.capture

import android.annotation.SuppressLint
import androidx.compose.foundation.background
