@SuppressLint("MissingPermission")
@Composable
fun CurrentRunScreen(
    screenModel: CaptureScreenModel,
    hexIndexer: HexIndexer,
    modifier: Modifier = Modifier
) {
    val state by screenModel.collectAsState()

    Box(modifier = modifier.fillMaxSize()) {
        CaptureMap(
            state = state,
            hexIndexer = hexIndexer,
            modifier = Modifier.fillMaxSize()
        )

        ElevatedCard(
            modifier = Modifier
                .align(Alignment.TopCenter)
                .padding(horizontal = 16.dp, vertical = 24.dp)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                Text(text = "Session Steps: ${state.sessionSteps}")
                Text(text = "Current Hex: ${state.currentHexId ?: "-"}")
                // UPDATE: Display the total count dynamically
                Text(text = "Captured Hexes: ${state.allCapturedHexes.size}")
            }
        }

        ExtendedFloatingActionButton(
            onClick = screenModel::onToggleTracking,
            containerColor = if (state.isTracking) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,
            contentColor = Color.White,
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(24.dp)
        ) {
            Text(if (state.isTracking) "Stop Capture" else "Start Capture")
        }
    }
}

@Composable
private fun CaptureMap(
    state: CaptureState,
    hexIndexer: HexIndexer,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    val lifecycle = LocalLifecycleOwner.current.lifecycle
    val mapView = remember {
        MapView(context).apply {
            onCreate(null)
            getMapAsync { mapLibreMap ->
                mapLibreMap.setStyle(Style.Builder().fromUri(BuildConfig.MAPTILER_STYLE_URL)) { style ->
                    ensureHexLayer(style)
                }
            }
        }
    }

    // UPDATE: Now merging all history to draw
    val hexCollectionJson = remember(state.allCapturedHexes, hexIndexer) {
        HexGeoJsonMapper.toFeatureCollectionJson(hexIndexer, state.allCapturedHexes)
    }

    val currentHexJson = remember(state.currentHexId, hexIndexer) {
        state.currentHexId?.let {
            HexGeoJsonMapper.toFeatureCollectionJson(hexIndexer, listOf(it))
        } ?: EMPTY_FEATURE_COLLECTION
    }

    // UPDATE: The Camera Engine
    // This moves the map view to follow your location while running
    LaunchedEffect(state.currentLocation) {
        state.currentLocation?.let { loc ->
            mapView.getMapAsync { map ->
                val position = CameraPosition.Builder()
                    .target(LatLng(loc.latitude, loc.longitude))
                    .zoom(16.0)
                    .build()
                map.animateCamera(CameraUpdateFactory.newCameraPosition(position), 1000)
            }
        }
    }

    DisposableEffect(lifecycle, mapView) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_START -> mapView.onStart()
                Lifecycle.Event.ON_RESUME -> mapView.onResume()
                Lifecycle.Event.ON_PAUSE -> mapView.onPause()
                Lifecycle.Event.ON_STOP -> mapView.onStop()
                else -> Unit
            }
        }
        lifecycle.addObserver(observer)
        onDispose {
            lifecycle.removeObserver(observer)
            mapView.onDestroy()
        }
    }

    Box(modifier = modifier) {
        AndroidView(
            factory = { mapView },
            modifier = Modifier.fillMaxSize(),
            update = { view ->
                view.getMapAsync { mapLibreMap ->
                    mapLibreMap.getStyle { style ->
                        ensureHexLayer(style)
                        style.getSourceAs<GeoJsonSource>(HEX_SOURCE_ID)?.setGeoJson(hexCollectionJson)
                        style.getSourceAs<GeoJsonSource>(CURRENT_HEX_SOURCE_ID)?.setGeoJson(currentHexJson)
                    }
                }
            }
        )

        if (BuildConfig.MAPTILER_API_KEY.isBlank()) {
            Text(
                text = "MapTiler key missing (.env)",
                color = Color.White,
                modifier = Modifier
                    .align(Alignment.TopStart)
                    .statusBarsPadding()
                    .padding(12.dp)
                    .background(Color(0xAA000000))
                    .padding(horizontal = 10.dp, vertical = 6.dp)
            )
        }
    }
}

private fun ensureHexLayer(style: Style) {
    val labelLayerId = when {
        style.getLayer("road-label") != null -> "road-label"
        style.getLayer("waterway-label") != null -> "waterway-label"
        else -> null
    }

    if (style.getSource(HEX_SOURCE_ID) == null) {
        style.addSource(GeoJsonSource(HEX_SOURCE_ID, EMPTY_FEATURE_COLLECTION))
    }
    if (style.getLayer(HEX_FILL_LAYER_ID) == null) {
        val capturedHexLayer = FillLayer(HEX_FILL_LAYER_ID, HEX_SOURCE_ID).withProperties(
            fillColor("#00C853"),
            fillOpacity(0.35f)
        )

        if (labelLayerId != null) {
            style.addLayerBelow(capturedHexLayer, labelLayerId)
        } else {
            style.addLayer(capturedHexLayer)
        }
    }

    if (style.getSource(CURRENT_HEX_SOURCE_ID) == null) {
        style.addSource(GeoJsonSource(CURRENT_HEX_SOURCE_ID, EMPTY_FEATURE_COLLECTION))
    }
    if (style.getLayer(CURRENT_HEX_FILL_LAYER_ID) == null) {
        val currentHexLayer = FillLayer(CURRENT_HEX_FILL_LAYER_ID, CURRENT_HEX_SOURCE_ID).withProperties(
            fillColor("#FFA500"),
            fillOpacity(0.5f)
        )
        if (labelLayerId != null) {
            style.addLayerBelow(currentHexLayer, labelLayerId)
        } else {
            style.addLayer(currentHexLayer)
        }
    }
}

private const val HEX_SOURCE_ID = "captured-hex-source"
private const val HEX_FILL_LAYER_ID = "captured-hex-fill-layer"
private const val CURRENT_HEX_SOURCE_ID = "current-hex-source"
private const val CURRENT_HEX_FILL_LAYER_ID = "current-hex-fill-layer"
private const val EMPTY_FEATURE_COLLECTION = "{\"type\":\"FeatureCollection\",\"features\":[]}"

